-- RYZE starter exercise catalog.
--
-- Platform-owned seed data written from scratch for RYZE's own Exercise
-- Library. Names, descriptions, instructions and alternative links are the
-- project's own original copy; nothing is imported from external libraries or
-- services. Instructions describe standard execution and are stored verbatim
-- as the catalog baseline (trainers may override per assignment).
--
-- Difficulty vocabulary: Beginner / Intermediate / Advanced.
-- Movement category vocabulary: Compound / Isolation / Core / Cardio /
-- Plyometric / Mobility.

INSERT INTO exercises
    (id, name, description, target_muscles, equipment, difficulty, video_url, image_url,
     primary_muscle_group, secondary_muscle_groups, movement_category, instructions)
VALUES
('d91e2f00-0000-4000-8000-000000000001','Barbell Bench Press','A horizontal push that builds pressing strength across the whole upper body.','Chest, Triceps, Shoulders','Barbell, Bench','Intermediate',NULL,NULL,'Chest','Triceps, Shoulders','Compound','Lie on a flat bench with your feet planted and take a shoulder-width grip. Lower the barbell to mid-chest with control, keeping the elbows at a comfortable angle. Press back up until the arms are straight without lifting the hips.'),
('d91e2f00-0000-4000-8000-000000000002','Dumbbell Bench Press','The dumbbell version of the bench press, with a larger range of motion for each arm.','Chest, Triceps, Shoulders','Dumbbells, Bench','Intermediate',NULL,NULL,'Chest','Triceps, Shoulders','Compound','Lie on a flat bench holding a dumbbell in each hand at chest height. Lower both dumbbells until the elbows pass the torso mid-line. Press them back up and together, keeping the wrists stacked over the elbows.'),
('d91e2f00-0000-4000-8000-000000000003','Incline Barbell Bench Press','A bench press performed on an incline to target the upper chest.','Upper Chest, Shoulders, Triceps','Barbell, Bench','Intermediate',NULL,NULL,'Chest','Shoulders, Triceps','Compound','Set the bench to a low incline and lie down with the bar above your collarbones. Lower the bar to the upper chest with control. Press up and slightly back, finishing directly over the shoulders.'),
('d91e2f00-0000-4000-8000-000000000004','Push-Up','A bodyweight push that builds pressing strength and core stability anywhere.','Chest, Triceps, Shoulders, Core','Bodyweight','Beginner',NULL,NULL,'Chest','Triceps, Shoulders, Abs','Compound','Place your hands slightly wider than the shoulders and form a straight line from head to heels. Lower your chest towards the floor while keeping the elbows tucked. Press back up to a fully extended position without sagging the hips.'),
('d91e2f00-0000-4000-8000-000000000005','Cable Chest Fly','An isolation fly that works the chest through a wide horizontal arc.','Chest','Cable Machine','Beginner',NULL,NULL,'Chest','Shoulders','Isolation','Set the pulleys to chest height and step forward with one foot for balance. With a slight bend in the elbows, bring the handles together in front of the chest. Return slowly through the same arc until a comfortable stretch is felt.'),
('d91e2f00-0000-4000-8000-000000000006','Chest Dip','A weighted bodyweight dip that develops the lower chest and triceps.','Chest, Triceps','Dip Bars, Weight Belt','Advanced',NULL,NULL,'Chest','Triceps, Shoulders','Compound','Support yourself on parallel bars with straight arms and legs tucked. Lower until the shoulders drop below the elbows, leaning slightly forward. Press back to full lockout, keeping the movement smooth and controlled.'),
('d91e2f00-0000-4000-8000-000000000007','Deadlift','A full-body hinge that develops the posterior chain and grip strength.','Back, Glutes, Hamstrings','Barbell','Intermediate',NULL,NULL,'Back','Glutes, Hamstrings, Lower Back','Compound','Stand with the bar over mid-foot and grip it just outside the legs. Brace your core, flatten the back and drive through the floor to stand up tall. Lower the bar under control, hinging at the hips with a straight spine.'),
('d91e2f00-0000-4000-8000-000000000008','Pull-Up','A vertical pull that builds the back and arms using only bodyweight.','Back, Biceps','Pull-Up Bar','Intermediate',NULL,NULL,'Back','Biceps, Forearms','Compound','Hang from the bar with an overhand grip slightly wider than the shoulders. Pull your chest towards the bar by driving the elbows down and back. Lower under control to a full hang without swinging.'),
('d91e2f00-0000-4000-8000-000000000009','Lat Pulldown','A machine vertical pull that builds the latissimus dorsi for beginners.','Back, Biceps','Cable Machine','Beginner',NULL,NULL,'Back','Biceps','Compound','Sit at the pulley station and grip the bar slightly wider than the shoulders. Pull the bar to the top of the chest, leading with the elbows. Return slowly until the arms are fully extended, keeping the torso upright.'),
('d91e2f00-0000-4000-8000-000000000010','Seated Cable Row','A horizontal pull that builds the mid-back while sitting.','Middle Back, Biceps','Cable Machine','Beginner',NULL,NULL,'Back','Biceps, Rear Shoulders','Compound','Sit facing the pulley with knees slightly bent and a straight spine. Pull the handle to the lower ribs, squeezing the shoulder blades together. Extend the arms fully before the next rep, keeping a controlled rhythm.'),
('d91e2f00-0000-4000-8000-000000000011','Bent-Over Barbell Row','A free-weight horizontal pull that develops the middle back and lats.','Middle Back','Barbell','Intermediate',NULL,NULL,'Back','Biceps, Lower Back','Compound','Hinge at the hips until the torso is close to parallel with a flat back. Pull the bar to the lower ribs, driving the elbows back. Lower the bar with control while keeping the position fixed.'),
('d91e2f00-0000-4000-8000-000000000012','Single-Arm Dumbbell Row','A unilateral row that builds back strength with a reduced lower-back demand.','Back','Dumbbell, Bench','Beginner',NULL,NULL,'Back','Biceps, Lower Back','Compound','Brace one hand and one knee on a bench, holding a dumbbell in the other hand. Row the weight to the hip, keeping the elbow close to the body. Lower slowly without twisting the torso, then switch sides.'),
('d91e2f00-0000-4000-8000-000000000013','Overhead Barbell Press','A standing press that builds the shoulders and upper chest strength.','Shoulders, Triceps','Barbell','Intermediate',NULL,NULL,'Shoulders','Triceps, Core','Compound','Stand with the bar at shoulder height and brace the core and glutes. Press the bar straight overhead until the arms lock out. Lower it back to the shoulders with control, keeping the ribs down.'),
('d91e2f00-0000-4000-8000-000000000014','Seated Dumbbell Shoulder Press','A seated press that isolates the deltoids with dumbbells.','Shoulders, Triceps','Dumbbells, Bench','Beginner',NULL,NULL,'Shoulders','Triceps','Compound','Sit on a bench with back support, dumbbells at shoulder height. Press both weights overhead until the arms are extended. Lower with control to shoulder height, avoiding excessive arching of the lower back.'),
('d91e2f00-0000-4000-8000-000000000015','Lateral Raise','An isolation movement that builds the side deltoid.','Shoulders, Traps','Dumbbells','Beginner',NULL,NULL,'Shoulders','','Isolation','Stand with a dumbbell in each hand and a slight bend in the elbows. Raise the arms out to the sides until they reach shoulder height. Lower slowly under control, avoiding momentum from the hips.'),
('d91e2f00-0000-4000-8000-000000000016','Front Raise','An isolation movement for the front deltoid.','Shoulders','Dumbbells','Beginner',NULL,NULL,'Shoulders','Chest','Isolation','Stand upright holding dumbbells in front of the thighs. Raise one or both arms forward to shoulder height with straight wrists. Lower slowly, keeping the core braced and the movement smooth.'),
('d91e2f00-0000-4000-8000-000000000017','Face Pull','A cable pull for the rear deltoids, upper back and postural muscles.','Rear Shoulders, Upper Back','Cable Machine','Beginner',NULL,NULL,'Shoulders','Back, Traps','Isolation','Set the rope pulley at eye height and step back with a tall posture. Pull the rope towards the face, separating the ends so the hands travel past the ears. Return slowly, keeping the torso still.'),
('d91e2f00-0000-4000-8000-000000000018','Arnold Press','A rotating dumbbell press that works the shoulders through a wide arc.','Shoulders, Triceps','Dumbbells','Intermediate',NULL,NULL,'Shoulders','Triceps','Compound','Start with dumbbells at shoulder height, palms facing you. As you press overhead, rotate the wrists so the palms face forward at the top. Reverse the rotation while lowering back to the start.'),
('d91e2f00-0000-4000-8000-000000000019','Barbell Curl','The classic elbow-flexion movement for overall biceps development.','Biceps','Barbell','Beginner',NULL,NULL,'Biceps','Forearms','Isolation','Stand holding a barbell with an underhand grip, arms extended. Curl it to the front of the shoulders without swinging the body. Lower under control to a full extension.'),
('d91e2f00-0000-4000-8000-000000000020','Dumbbell Hammer Curl','A neutral-grip curl that builds the biceps and brachialis.','Biceps, Forearms','Dumbbells','Beginner',NULL,NULL,'Biceps','Forearms','Isolation','Hold the dumbbells at your sides with palms facing each other. Curl the weights towards the shoulders keeping the wrists neutral. Lower slowly to the start.'),
('d91e2f00-0000-4000-8000-000000000021','Incline Dumbbell Curl','A curl on an incline bench that emphasises a deep biceps stretch.','Biceps','Dumbbells, Bench','Intermediate',NULL,NULL,'Biceps','Forearms','Isolation','Lie back on an incline bench with your arms hanging straight down. Curl the dumbbells towards the shoulders without letting the elbows drift forward. Lower slowly through a full stretch.'),
('d91e2f00-0000-4000-8000-000000000022','Triceps Pushdown','A cable isolation movement for the triceps.','Triceps','Cable Machine','Beginner',NULL,NULL,'Triceps','','Isolation','Face the pulley with the bar at chest height and elbows tucked. Push the bar down until the arms are straight, keeping the upper arms still. Return slowly to the start, resisting the weight.'),
('d91e2f00-0000-4000-8000-000000000023','Close-Grip Bench Press','A narrow-grip press that emphasises the triceps.','Triceps, Chest','Barbell, Bench','Intermediate',NULL,NULL,'Triceps','Chest, Shoulders','Compound','Lie on a flat bench and grip the bar inside shoulder width. Lower the bar to the lower chest with the elbows tucked close. Press back up until lockout, keeping the wrists neutral.'),
('d91e2f00-0000-4000-8000-000000000024','Overhead Cable Triceps Extension','A cable extension that builds triceps length under tension.','Triceps','Cable Machine','Beginner',NULL,NULL,'Triceps','Shoulders','Isolation','Set a rope on a low pulley and face away from the stack. Raise the rope overhead and extend the elbows until the arms straighten. Return slowly, keeping the upper arms pointed forward.'),
('d91e2f00-0000-4000-8000-000000000025','Wrist Curl','An isolation movement for the forearm flexors.','Forearms','Dumbbells, Bench','Beginner',NULL,NULL,'Forearms','Biceps','Isolation','Sit with your forearms resting on your thighs or a bench, palms up. Curl the wrists upwards, squeezing the forearms, then lower slowly below parallel.'),
('d91e2f00-0000-4000-8000-000000000026','Back Squat','A barbell squat that builds the legs and trunk as a full-body pillar.','Quads, Glutes','Barbell','Intermediate',NULL,NULL,'Quads','Glutes, Core, Hamstrings','Compound','Rest the bar across the upper back and stand with feet shoulder-width apart. Sit down into the hips, keeping the chest up and knees tracking over the toes. Drive back up to the start with the whole foot planted.'),
('d91e2f00-0000-4000-8000-000000000027','Front Squat','A barbell squat with the load racked in the front for an upright torso.','Quads','Barbell','Advanced',NULL,NULL,'Quads','Core, Glutes','Compound','Rack the bar across the front shoulders with elbows high. Squat down with a tall chest, keeping the elbows up and the knees stable. Stand back up driving through the whole foot.'),
('d91e2f00-0000-4000-8000-000000000028','Goblet Squat','A dumbbell or kettlebell squat that teaches a clean upright pattern.','Quads, Glutes','Kettlebell, Dumbbell','Beginner',NULL,NULL,'Quads','Glutes, Core','Compound','Hold a kettlebell tight against the chest and stand with feet shoulder-width. Squat down between the knees, keeping the chest tall and elbows inside. Push the floor away to stand back up.'),
('d91e2f00-0000-4000-8000-000000000029','Leg Press','A machine squat pattern that loads the legs with back support.','Quads, Glutes','Leg Press Machine','Beginner',NULL,NULL,'Quads','Glutes','Compound','Sit in the leg press with feet shoulder-width on the platform. Lower the platform until the knees reach a comfortable depth. Press back up without locking the knees hard or lifting the hips.'),
('d91e2f00-0000-4000-8000-000000000030','Walking Lunge','A loaded lunge that builds single-leg strength and balance.','Quads, Glutes','Dumbbells','Beginner',NULL,NULL,'Quads','Glutes, Hamstrings','Compound','Hold dumbbells at your sides and step forward into a lunge. Lower until both knees reach near ninety degrees, keeping the torso upright. Push through the front heel to step the back leg through and continue.'),
('d91e2f00-0000-4000-8000-000000000031','Leg Extension','A machine isolation lift for the quadriceps.','Quads','Leg Extension Machine','Beginner',NULL,NULL,'Quads','','Isolation','Sit in the machine with the pad above the ankles. Extend the knees to raise the pad until the legs are straight. Lower slowly, resisting the weight on the way down.'),
('d91e2f00-0000-4000-8000-000000000032','Romanian Deadlift','A hip-hinge movement that targets the hamstrings and glutes.','Hamstrings, Glutes','Barbell, Dumbbells','Intermediate',NULL,NULL,'Hamstrings','Glutes, Lower Back','Compound','Stand with the bar at the thighs and a soft knee bend. Push the hips back, sliding the bar down the legs until a strong hamstring stretch is felt. Drive the hips forward to stand tall, squeezing the glutes.'),
('d91e2f00-0000-4000-8000-000000000033','Hip Thrust','A glute-focused hip extension performed with the upper back on a bench.','Glutes','Barbell, Bench','Intermediate',NULL,NULL,'Glutes','Hamstrings','Compound','Sit with your upper back against a bench and roll a padded bar over your hips. Drive through the heels to lift the hips until the torso is horizontal. Squeeze the glutes at the top, then lower under control.'),
('d91e2f00-0000-4000-8000-000000000034','Lying Leg Curl','A machine curl for the hamstrings in a prone position.','Hamstrings','Leg Curl Machine','Beginner',NULL,NULL,'Hamstrings','Glutes','Isolation','Lie face down with the pad above the heels. Curl the heels towards the glutes, squeezing the hamstrings. Return slowly to a full extension.'),
('d91e2f00-0000-4000-8000-000000000035','Glute Bridge','A bodyweight hip extension for the glutes and hamstrings.','Glutes, Hamstrings','Bodyweight','Beginner',NULL,NULL,'Glutes','Hamstrings','Compound','Lie on your back with knees bent and feet flat on the floor. Drive through the heels to lift the hips until the body forms a straight line. Squeeze the glutes at the top, then lower with control.'),
('d91e2f00-0000-4000-8000-000000000036','Standing Calf Raise','A standing calf raise for the gastrocnemius.','Calves','Calf Raise Machine, Bodyweight','Beginner',NULL,NULL,'Calves','','Isolation','Stand with the balls of the feet on a raised surface and the pad on the shoulders. Rise onto the toes as high as possible, then lower below the level of the step for a full stretch.'),
('d91e2f00-0000-4000-8000-000000000037','Plank','A static hold that builds core and postural stability.','Abs, Core','Bodyweight','Beginner',NULL,NULL,'Abs','Core, Shoulders','Core','Rest on the forearms with the body in a straight line from head to heels. Brace the abs and glutes without letting the hips sag or pike. Hold with even breathing for the prescribed time.'),
('d91e2f00-0000-4000-8000-000000000038','Hanging Knee Raise','A hanging core raise that works the lower abs and grip.','Abs','Pull-Up Bar','Intermediate',NULL,NULL,'Abs','Hip Flexors, Forearms','Core','Hang from a bar with straight arms and brace the shoulders. Raise the knees towards the chest without swinging. Lower the legs slowly to the start.'),
('d91e2f00-0000-4000-8000-000000000039','Russian Twist','A seated rotation for the obliques and core.','Obliques','Medicine Ball, Bodyweight','Beginner',NULL,NULL,'Obliques','Abs','Core','Sit with the knees bent and lean the torso back slightly. Rotate the trunk side to side, bringing the hands or ball beside the hips. Keep the chest tall and the movement controlled.'),
('d91e2f00-0000-4000-8000-000000000040','Crunch','A simple trunk-flexion movement for the upper abs.','Abs','Bodyweight','Beginner',NULL,NULL,'Abs','Obliques','Core','Lie on your back with knees bent and hands lightly behind the head. Curl the shoulders off the floor by contracting the abs. Lower back down slowly without yanking the neck.'),
('d91e2f00-0000-4000-8000-000000000041','Dead Bug','A floor core exercise that trains anti-extension and limb control.','Abs','Bodyweight','Beginner',NULL,NULL,'Abs','Hip Flexors, Core','Core','Lie on your back with arms up and knees above the hips. Lower the opposite arm and leg towards the floor while keeping the back flat. Return to the start and switch sides, keeping the movement slow.'),
('d91e2f00-0000-4000-8000-000000000042','Side Plank','A lateral core hold for the obliques and shoulder stability.','Obliques','Bodyweight','Beginner',NULL,NULL,'Obliques','Abs, Shoulders','Core','Lie on your side with the forearm under the shoulder and feet stacked. Lift the hips until the body forms a straight line from head to feet. Hold with the core braced, then repeat on the other side.'),
('d91e2f00-0000-4000-8000-000000000043','Treadmill Run','A steady-state run on a treadmill used for conditioning and fat loss.','Full Body','Treadmill','Beginner',NULL,NULL,'Full Body','Calves, Glutes','Cardio','Start at a comfortable walking pace and increase until you reach a steady run. Keep a relaxed upright posture with a short stride. Cool down gradually at the end of the interval.'),
('d91e2f00-0000-4000-8000-000000000044','Jump Rope','A fast skipping drill that builds conditioning and calf endurance.','Calves','Jump Rope','Intermediate',NULL,NULL,'Calves','Abs, Shoulders','Cardio','Hold the rope handles at hip height and spin it with the wrists. Jump on the balls of the feet with small, soft bounces. Keep a steady rhythm and land quietly with the knees soft.'),
('d91e2f00-0000-4000-8000-000000000045','Box Jump','A plyometric jump onto a box for power and lower-body explosiveness.','Quads, Glutes','Box','Intermediate',NULL,NULL,'Quads','Glutes, Calves','Plyometric','Stand in front of a sturdy box with feet shoulder-width. Swing the arms and jump explosively onto the box, landing soft with knees bent. Step down under control instead of jumping back.'),
('d91e2f00-0000-4000-8000-000000000046','Burpee','A full-body conditioning drill combining a squat, push-up and jump.','Full Body','Bodyweight','Intermediate',NULL,NULL,'Full Body','Abs, Quads, Shoulders','Cardio','From standing, squat down and place the hands on the floor. Kick the feet back into a plank, perform a push-up, then jump the feet forward. Stand and jump into the air, then repeat at a steady pace.'),
('d91e2f00-0000-4000-8000-000000000047','Hip Flexor Stretch','A kneeling stretch that opens the hips and improves squat posture.','Hips','Bodyweight','Beginner',NULL,NULL,'Hips','Abs','Mobility','Kneel on one knee with the other foot planted forward. Squeeze the glute of the kneeling leg and shift the hips forward. Hold the position for the prescribed time, then switch sides.'),
('d91e2f00-0000-4000-8000-000000000048','Hamstring Stretch','A simple seated stretch for the hamstrings and lower back.','Hamstrings','Bodyweight','Beginner',NULL,NULL,'Hamstrings','Lower Back','Mobility','Sit with one leg extended and the other foot against the inner thigh. Hinge forward from the hips towards the extended leg with a flat back. Hold for the prescribed time, then switch legs.');

